CREATE OR REPLACE FUNCTION public._auto_create_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_email TEXT; v_auth_id UUID;
BEGIN
  v_email := lower(NEW.username) || '@thecoffee.internal';
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE email = v_email) THEN
    v_auth_id := gen_random_uuid();
    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, created_at, updated_at,
      raw_app_meta_data, raw_user_meta_data, is_super_admin,
      confirmation_token, recovery_token, email_change_token_new,
      email_change, phone_change, phone_change_token,
      email_change_confirm_status, is_sso_user
    ) VALUES (
      v_auth_id, '00000000-0000-0000-0000-000000000000',
      'authenticated', 'authenticated', v_email,
      crypt('[REDACTADO]', gen_salt('bf', 10)),
      NOW(), NOW(), NOW(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      jsonb_build_object('username', NEW.username), false,
      '', '', '', '', '', '', 0, false
    );
    NEW.auth_uid := v_auth_id;
  ELSE
    SELECT id INTO v_auth_id FROM auth.users WHERE email = v_email;
    NEW.auth_uid := v_auth_id;
  END IF;
  NEW.debe_cambiar_pass := true;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_reset_password_for_user(p_internal_id uuid, p_new_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'extensions', 'public', 'auth'
AS $function$
DECLARE
  v_auth_uid uuid;
  v_correo   text;
  v_found    uuid;
BEGIN
  SELECT auth_uid, correo INTO v_auth_uid, v_correo
  FROM public.usuarios WHERE id = p_internal_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Usuario no encontrado');
  END IF;

  -- Marcar que debe cambiar contraseña al próximo login
  UPDATE public.usuarios SET debe_cambiar_pass = true WHERE id = p_internal_id;

  IF v_auth_uid IS NOT NULL THEN
    UPDATE auth.users
    SET encrypted_password = crypt(p_new_password, gen_salt('bf'))
    WHERE id = v_auth_uid;
    RETURN jsonb_build_object('ok', true);
  END IF;

  IF v_correo IS NOT NULL THEN
    SELECT id INTO v_found FROM auth.users WHERE email = v_correo LIMIT 1;
  END IF;

  IF v_found IS NOT NULL THEN
    UPDATE auth.users
    SET encrypted_password = crypt(p_new_password, gen_salt('bf'))
    WHERE id = v_found;
    UPDATE public.usuarios SET auth_uid = v_found WHERE id = p_internal_id;
    RETURN jsonb_build_object('ok', true);
  END IF;

  IF v_correo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin correo: no se puede crear cuenta');
  END IF;

  INSERT INTO auth.users (
    instance_id, id, aud, role, email,
    encrypted_password, email_confirmed_at,
    created_at, updated_at,
    confirmation_token, raw_app_meta_data, raw_user_meta_data
  ) VALUES (
    '00000000-0000-0000-0000-000000000000'::uuid,
    gen_random_uuid(),
    'authenticated', 'authenticated',
    v_correo,
    crypt(p_new_password, gen_salt('bf')),
    now(), now(), now(),
    '', '{"provider":"email","providers":["email"]}', '{}'
  )
  RETURNING id INTO v_found;

  UPDATE public.usuarios SET auth_uid = v_found WHERE id = p_internal_id;
  RETURN jsonb_build_object('ok', true, 'created', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.authenticate_and_migrate(p_username text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_result JSONB; v_auth_uid UUID;
BEGIN
  SELECT authenticate_user(p_username, p_password) INTO v_result;
  IF v_result IS NOT NULL AND (v_result->>'error') IS NULL THEN
    SELECT auth_uid INTO v_auth_uid FROM usuarios WHERE username = p_username;
    IF v_auth_uid IS NOT NULL THEN
      UPDATE auth.users
      SET encrypted_password = crypt(p_password, gen_salt('bf', 10)), updated_at = NOW()
      WHERE id = v_auth_uid;
    END IF;
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.authenticate_user(p_username text, p_password text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user usuarios%ROWTYPE;
  v_match boolean := false;
BEGIN
  SELECT * INTO v_user FROM usuarios WHERE username = lower(trim(p_username));
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF v_user.password IS NULL OR v_user.password = '' THEN
    RETURN NULL;
  ELSIF v_user.password LIKE '$2%' THEN
    v_match := (crypt(p_password, v_user.password) = v_user.password);
  ELSIF v_user.password LIKE 'pbkdf2:%' THEN
    RETURN json_build_object('error', 'pbkdf2_reset_required');
  ELSE
    v_match := (v_user.password = p_password);
  END IF;

  IF NOT v_match THEN RETURN NULL; END IF;
  IF v_user.activo = false THEN
    RETURN json_build_object('error', 'inactive');
  END IF;

  IF v_user.password NOT LIKE '$2%' THEN
    UPDATE usuarios SET password = crypt(p_password, gen_salt('bf', 12)) WHERE id = v_user.id;
  END IF;

  UPDATE usuarios SET ultimo_acceso = now() WHERE id = v_user.id;

  RETURN json_build_object(
    'id', v_user.id, 'username', v_user.username, 'nombre', v_user.nombre,
    'rol', v_user.rol, 'activo', v_user.activo, 'debe_cambiar_pass', v_user.debe_cambiar_pass,
    'permisos', v_user.permisos, 'supplier_key', v_user.supplier_key,
    'subtipo', v_user.subtipo, 'puede_ver_avance', v_user.puede_ver_avance,
    'correo', v_user.correo, 'telefono', v_user.telefono, 'ultimo_acceso', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.change_user_password(p_user_id uuid, p_current_password text, p_new_password text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_stored text;
  v_match boolean := false;
BEGIN
  SELECT password INTO v_stored FROM usuarios WHERE id = p_user_id;
  IF NOT FOUND THEN RETURN json_build_object('ok', false, 'error', 'user_not_found'); END IF;

  IF v_stored LIKE '$2%' THEN
    v_match := (crypt(p_current_password, v_stored) = v_stored);
  ELSIF v_stored LIKE 'pbkdf2:%' THEN
    v_match := true;
  ELSE
    v_match := (v_stored = p_current_password);
  END IF;

  IF NOT v_match THEN RETURN json_build_object('ok', false, 'error', 'wrong_password'); END IF;

  UPDATE usuarios
  SET password = crypt(p_new_password, gen_salt('bf', 12)), debe_cambiar_pass = false
  WHERE id = p_user_id;

  RETURN json_build_object('ok', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.coffee_mail_worker_v1(p_action text, p_limit integer DEFAULT 20, p_delivery_id uuid DEFAULT NULL::uuid, p_lease_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb; current_status text;
begin
 if p_action='claim' then
  if not coalesce((select enabled from coffee_mail.settings where singleton),false) then
   return jsonb_build_object('deliveries','[]'::jsonb,'paused',true);
  end if;
  if p_limit is null or p_limit not between 1 and 50 then raise exception 'Límite inválido';end if;
  update coffee_mail.deliveries set status='uncertain',last_error='La ejecución expiró; revisar antes de reenviar'
   where status='claimed' and claimed_at < now()-interval '15 minutes';
  update coffee_mail.deliveries d set status='cancelled',last_error='Apertura eliminada o fuera de en_proceso'
   from coffee_mail.events e where d.event_id=e.id and d.status='pending'
    and not exists(select 1 from public.aperturas a where a.id=e.apertura_id and a.estatus='en_proceso');
  -- El destinatario debe seguir autorizado y activo al reclamar la entrega.
  update coffee_mail.deliveries d set status='cancelled',last_error='Cuenta o correo del proveedor ya no está activo'
   where d.status='pending' and not exists(select 1 from public.usuarios u where u.rol='proveedor'
    and u.activo=true and u.supplier_key=d.supplier_key and lower(trim(u.correo))=d.recipient);
  with candidates as (
   select d.id from coffee_mail.deliveries d where status='pending' and (
    (select test_apertura_id from coffee_mail.settings where singleton) is null or exists(
     select 1 from coffee_mail.events e where e.id=d.event_id and e.apertura_id=(select test_apertura_id from coffee_mail.settings where singleton)))
    order by created_at,id
    limit p_limit for update skip locked
  ), claimed as (
   update coffee_mail.deliveries d set status='claimed',lease_token=gen_random_uuid(),claimed_at=now()
    from candidates c where c.id=d.id returning d.*
  ) select coalesce(jsonb_agg(jsonb_build_object('delivery_id',d.id,'event_id',d.event_id,
    'lease_token',d.lease_token,'status',d.status,'to',d.recipient,'supplier_name',s.name,
    'apertura_id',e.apertura_id,'sucursal',e.sucursal,'old_date',e.old_date,'new_date',e.new_date,
    'changed_at',e.created_at,'from',(select sender from coffee_mail.settings where singleton))),'[]'::jsonb)
    into result from claimed d join coffee_mail.events e on e.id=d.event_id
    join coffee_mail.suppliers s on s.supplier_key=d.supplier_key;
  return jsonb_build_object('deliveries',result,'paused',false);
 elsif p_action in ('ack','uncertain') then
  if p_delivery_id is null or p_lease_token is null then raise exception 'Entrega inválida';end if;
  select status into current_status from coffee_mail.deliveries where id=p_delivery_id and lease_token=p_lease_token for update;
  if not found then raise exception 'Entrega no reconocida';end if;
  if current_status='sent' then return jsonb_build_object('status','sent');end if;
  if current_status not in ('claimed','uncertain') then raise exception 'Estado inválido';end if;
  if p_action='ack' then
   update coffee_mail.deliveries set status='sent',sent_at=now(),last_error=null where id=p_delivery_id;
   return jsonb_build_object('status','sent');
  end if;
  update coffee_mail.deliveries set status='uncertain',last_error='Fallo SMTP o resultado incierto; no reenviar automáticamente' where id=p_delivery_id;
  return jsonb_build_object('status','uncertain');
 else raise exception 'Acción inválida';end if;
end;$function$

CREATE OR REPLACE FUNCTION public.coffee_sync_aperturas_v1(p_rows jsonb, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r jsonb;
  ap public.aperturas%rowtype;
  nueva date;
  anterior date;
  resultado jsonb := '[]'::jsonb;
  vistos text[] := array[]::text[];
begin
  if jsonb_typeof(p_rows) is distinct from 'array' then raise exception 'Lote inválido'; end if;
  if jsonb_array_length(p_rows) not between 1 and 500 then raise exception 'Tamaño inválido'; end if;
  -- Orden estable de locks: dos ejecuciones concurrentes no toman filas en orden inverso.
  for r in select value from jsonb_array_elements(p_rows) order by value->>'id' loop
    if jsonb_typeof(r->'id') is distinct from 'string' or (r->>'id') !~ '^[0-9]{1,12}$' then raise exception 'ID inválido'; end if;
    if (r->>'id') = any(vistos) then raise exception 'ID duplicado'; end if;
    vistos := array_append(vistos,r->>'id');
    if coalesce(r->>'fecha','') !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' then raise exception 'Fecha inválida'; end if;
    nueva := (r->>'fecha')::date;
    select * into ap from public.aperturas where id = r->>'id' for update;
    if not found then
      if p_apply then raise exception 'ID inexistente: %',r->>'id'; end if;
      resultado := resultado || jsonb_build_array(jsonb_build_object('id',r->>'id','estado','no_encontrado'));
      continue;
    end if;
    if ap.estatus is distinct from 'en_proceso' then
      if p_apply then raise exception 'Estado no permitido: %',ap.id; end if;
      resultado := resultado || jsonb_build_array(jsonb_build_object('id',ap.id,'sucursal',ap.sucursal,'estado','excluido','anterior',ap.fecha,'fecha',nueva));
      continue;
    end if;
    if p_apply then
      if not (r ? 'anterior') then raise exception 'Falta fecha anterior'; end if;
      anterior := (r->>'anterior')::date;
      if ap.fecha is distinct from anterior then raise exception 'Conflicto: % cambió después de la revisión',ap.id; end if;
      if ap.fecha is distinct from nueva then
        update public.aperturas set fecha=nueva, updated_at=now() where id=ap.id;
        insert into public.historial(apertura_id,accion,descripcion,usuario,supplier_key)
        values(ap.id,'fecha_cambiada',jsonb_build_object(
          'anterior',ap.fecha,'nueva',nueva,'dias',nueva-ap.fecha,
          'responsable',null,'supplier_key',null,
          'motivo','Sincronización desde Google Sheets · Aperturas · Apertura REAL',
          'origen','google_sheets')::text,'Automatización Google Sheets',null);
      end if;
    end if;
    resultado := resultado || jsonb_build_array(jsonb_build_object('id',ap.id,'sucursal',ap.sucursal,
      'estado',case when ap.fecha is not distinct from nueva then 'sin_cambio' when p_apply then 'actualizado' else 'cambiar' end,
      'anterior',ap.fecha,'fecha',nueva));
  end loop;
  return resultado;
end;
$function$

CREATE OR REPLACE FUNCTION public.com_plan_sello_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  u record;
begin
  -- La fecha y hora también las pone el servidor (un reloj mal puesto o un cliente manipulado no puede inventar el "cuándo").
  if tg_table_name = 'com_plan_config_historial' then
    new.created_at := now();
    new.usuario_auth_uid := auth.uid();
  elsif tg_table_name = 'com_plan_config' then
    new.updated_at := now();
  end if;
  select usr.username, usr.nombre, usr.rol into u
    from public.usuarios usr
   where usr.auth_uid = auth.uid()
   limit 1;
  if found then
    if tg_table_name = 'com_plan_config_historial' then
      new.username := u.username;
      new.modificado_por := coalesce(u.nombre, u.username);
      new.rol := u.rol;
    elsif tg_table_name = 'com_plan_config' then
      new.actualizado_por := coalesce(u.nombre, u.username);
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE u RECORD; v_uid UUID;
BEGIN
  BEGIN v_uid := (event->>'user_id')::UUID;
  EXCEPTION WHEN OTHERS THEN RETURN event; END;
  IF v_uid IS NULL THEN RETURN event; END IF;
  SELECT id, username, nombre, rol, activo, parent_id, permisos, correo, debe_cambiar_pass
  INTO u FROM usuarios WHERE auth_uid = v_uid;
  IF u.id IS NULL THEN RETURN event; END IF;
  RETURN jsonb_set(event, '{claims}',
    (event->'claims') || jsonb_build_object(
      'db_id', u.id, 'username', COALESCE(u.username,''),
      'nombre', COALESCE(u.nombre,''), 'rol', COALESCE(u.rol,''),
      'activo', COALESCE(u.activo,false), 'parent_id', u.parent_id,
      'permisos', COALESCE(u.permisos,'{}'::jsonb),
      'correo', COALESCE(u.correo,''),
      'debe_cambiar_pass', COALESCE(u.debe_cambiar_pass,false)
    )
  );
EXCEPTION WHEN OTHERS THEN RETURN event;
END;
$function$

CREATE OR REPLACE FUNCTION public.evitar_doble_dueno_principal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  es_principal boolean;
  ya_existe_otro boolean;
begin
  select parent_id is null into es_principal
  from public.usuarios where id = new.usuario_id;

  if es_principal then
    select exists (
      select 1 from public.franquiciado_aperturas fa
      join public.usuarios u on u.id = fa.usuario_id
      where fa.apertura_id = new.apertura_id
        and u.parent_id is null
        and fa.usuario_id <> new.usuario_id
    ) into ya_existe_otro;

    if ya_existe_otro then
      raise exception 'Esta sucursal ya tiene un franquiciatario principal vinculado — nunca puede tener 2 a la vez. Desvincula al actual antes de asignar uno nuevo.';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_session_token(p_user_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_token TEXT;
BEGIN
  v_token := gen_random_uuid()::TEXT;
  UPDATE usuarios 
    SET session_token = v_token, session_exp = NOW() + INTERVAL '8 hours'
    WHERE id = p_user_id AND activo = true;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN v_token;
END;
$function$
